def calculate_entanglement_structure(self, rho):
    """
    Compute von Neumann entropy S = -Tr(ρ log₂ ρ) for each character pair
    Returns entanglement "weights" for UI visualization
    """
    from scipy.linalg import logm

    entanglement_matrix = {}
    char_names = list(self.characters.keys())

    for i, char1 in enumerate(char_names):
        for j, char2 in enumerate(char_names[i+1:], i+1):
            # Get qubits for this pair
            qubits1 = list(range(i*3, (i+1)*3))
            qubits2 = list(range(j*3, (j+1)*3))
            combined = qubits1 + qubits2

            # Partial trace to subsystem
            rho_sub = ptrace(rho, combined)

            # Von Neumann entropy (entanglement measure)
            rho_np = rho_sub.full()
            eigenvals = np.linalg.eigvalsh(rho_np)
            eigenvals = eigenvals[eigenvals > 1e-10]  # Filter numerical noise

            entropy = -np.sum(eigenvals * np.log2(eigenvals))

            # Normalize to [0,1] for UI (max entropy = log₂(dim))
            max_entropy = math.log2(rho_sub.shape[0])
            normalized = entropy / max_entropy if max_entropy > 0 else 0

            entanglement_matrix[f"{char1}-{char2}"] = normalized

    return entanglement_matrix


